def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    recent_len = min(10, n)
    recent = opp[n - recent_len:]
    recent_c = sum(1 for a in recent if a == 'C')
    recent_ratio = recent_c / recent_len

    total_c = sum(1 for a in opp if a == 'C')
    total_ratio = total_c / n

    # Detect long runs of sustained defection; avoid being exploited.
    if n >= 8:
        last8 = opp[-8:]
        d8 = 0
        for a in last8:
            if a == 'D':
                d8 += 1
            else:
                break
        if d8 >= 6:
            # Sustained defector; defect almost always, tiny reset chance.
            if rng.random() < 0.04:
                return 'C'
            return 'D'

    # Detect sustained cooperation; cooperate, rarely probe.
    if n >= 6:
        last6 = opp[-6:]
        if all(a == 'C' for a in last6):
            return 'C'

    # Count opponent's defections after our cooperation (exploitation signal).
    exploit = 0
    for i in range(n):
        if me[i] == 'C' and opp[i] == 'D':
            exploit += 1
    exploit_rate = exploit / n

    last_opp = opp[-1]
    last_me = me[-1]

    # If opponent defected on us while we cooperated, retaliate but with
    # forgiveness calibrated to their overall cooperativeness.
    if last_opp == 'D':
        # Consecutive opponent defections
        k = 0
        for i in range(n - 1, -1, -1):
            if opp[i] == 'D':
                k += 1
            else:
                break
        if k >= 3:
            # Repeated defection: mostly defect, occasionally probe.
            if rng.random() < 0.10:
                return 'C'
            return 'D'
        if k == 2:
            if recent_ratio > 0.6:
                return 'C' if rng.random() < 0.55 else 'D'
            return 'D' if rng.random() < 0.75 else 'C'
        # Single defection from opponent
        if last_me == 'D':
            # Mutual defection last round: try to break out towards CC.
            if recent_ratio > 0.3 or exploit_rate < 0.15:
                return 'C' if rng.random() < 0.6 else 'D'
            return 'C' if rng.random() < 0.3 else 'D'
        else:
            # We cooperated, they defected. Forgive if they are generally nice.
            if recent_ratio > 0.65:
                return 'C' if rng.random() < 0.8 else 'D'
            if recent_ratio > 0.4:
                return 'C' if rng.random() < 0.4 else 'D'
            if rng.random() < 0.15:
                return 'C'
            return 'D'

    # Opponent cooperated last round.
    if last_me == 'D':
        # Return to cooperation promptly to rebuild CC streaks.
        return 'C'

    # Both cooperated: keep cooperating, but be wary of pure exploiters.
    if total_ratio < 0.2 and n >= 10:
        # Opponent has been mostly defecting overall even though just cooperated.
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    # Occasional probing only very rarely, to avoid damaging CC streaks.
    if n >= 20 and n % 29 == 0 and rng.random() < 0.08:
        return 'D'

    return 'C'
